<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#c9e5ee"><title>Small Speech, Big Moment</title>
<style>
@font-face{font-family:Moon;src:url(data:font/ttf;base64,) format('truetype');font-display:swap}
:root{--sky:#c9e5ee;--ink:#143e52;--quiet:#36586a;--paper:#f8fcfd;--coral:#a92f22;--line:#86aebb}*{box-sizing:border-box}body{margin:0;background:var(--sky);color:var(--ink);font:17px/1.55 'Trebuchet MS',sans-serif;scrollbar-color:var(--ink) var(--sky)}::selection{background:var(--coral);color:white}a{color:inherit;text-underline-offset:4px}button,input,textarea{font:inherit;accent-color:var(--coral);caret-color:var(--coral)}button{min-height:48px;padding:12px 18px;border:1px solid var(--ink);border-radius:12px;background:transparent;color:var(--ink);cursor:pointer}button:hover{background:#e5f3f7}button:active{transform:translateY(1px)}button:disabled{opacity:.55;cursor:default}button:focus-visible,a:focus-visible,textarea:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid var(--coral);outline-offset:4px}[hidden]{display:none!important}h1,h2,h3{font-family:Moon,sans-serif;font-weight:500;line-height:1.08;text-wrap:balance}h1{font-size:clamp(2.9rem,6.2vw,5.3rem);letter-spacing:-.025em;margin:20px 0 12px;max-width:16ch}h2{font-size:2rem;margin:8px 0 14px}h3{font-size:1.5rem}p{max-width:68ch}nav{display:flex;justify-content:space-between;gap:15px;align-items:center;padding:16px 0;border-bottom:1px solid var(--line);font-size:14px}main,nav,footer{width:min(1120px,calc(100% - 48px));margin:auto}.opening{position:relative;padding:10px 0 24px}.opening p{max-width:63ch;margin:0}.scene{margin:0;position:relative}.scene img{display:block;width:100%;max-height:300px;object-fit:cover;object-position:center 52%;border-radius:18px}.scene figcaption{font-size:13px;margin:8px 0 0;color:var(--quiet)}.work{display:grid;grid-template-columns:1.12fr .88fr;gap:50px;margin:28px 0 40px;align-items:start}.progress{display:flex;align-items:center;justify-content:space-between;gap:16px;font-variant-numeric:tabular-nums;font-size:14px}.marks{display:flex;gap:5px}.marks span{width:24px;height:6px;background:var(--line);border-radius:2px}.marks .done{background:var(--ink)}.marks .current{background:var(--coral)}#instruction{margin:0 0 16px}.audition{font-size:clamp(1.1rem,2vw,1.35rem);line-height:1.5;background:var(--paper);padding:20px 24px;margin:0 0 18px;border-radius:12px;min-height:105px}#options{display:grid;gap:9px}#options button{text-align:left;padding:12px 16px;line-height:1.4}#options button[aria-pressed=true]{background:var(--ink);color:white}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}.primary{background:var(--coral);color:white;border-color:var(--coral);font-weight:bold}.primary:hover{background:#86261d}.actions .primary{flex:1}#feedback{min-height:74px;margin:15px 0 0;color:var(--quiet)}.manuscript{background:var(--paper);padding:28px;border-radius:2px 2px 18px 2px;box-shadow:0 14px 30px #143e5214}.manuscript summary{font-family:Moon,sans-serif;font-size:1.6rem;cursor:pointer;min-height:44px}.manuscript ol{padding:0;margin:22px 0 0;list-style:none;counter-reset:lines}.manuscript li{counter-increment:lines;margin:0 0 20px;position:relative;padding-left:30px;font-size:18px}.manuscript li:before{content:counter(lines);position:absolute;left:0;font-size:12px;top:5px;color:var(--quiet);font-variant-numeric:tabular-nums}.manuscript li.pending{color:var(--quiet);font-size:15px}.manuscript li.accepted{animation:ink .5s cubic-bezier(.16,1,.3,1)}@keyframes ink{from{color:var(--coral);filter:blur(.5px)}to{color:var(--ink);filter:blur(0)}}.note{font-size:14px;color:var(--quiet);margin-bottom:0}#finish{max-width:780px;margin:30px auto 45px}#finish h2{font-size:clamp(2.7rem,5vw,4rem)}textarea{display:block;width:100%;min-height:330px;background:var(--paper);border:1px solid var(--line);color:var(--ink);padding:22px;border-radius:12px;line-height:1.6;resize:vertical;margin:10px 0 20px}label{display:block}input[type=range]{width:180px;min-height:44px;vertical-align:middle}.listen{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.about{border-top:1px solid var(--line);padding:24px 0;display:grid;grid-template-columns:1fr 1fr;gap:45px}.about h3{margin:0 0 10px}.about p{font-size:15px;margin:0 0 12px}footer{padding:12px 0 28px;color:var(--quiet);font-size:13px}#audioStatus{font-size:14px;min-height:24px}#next{width:100%}
@media(max-width:700px){main,nav,footer{width:calc(100% - 36px)}nav span{max-width:16ch;text-align:right}h1{font-size:3.1rem;margin:14px 0 12px;max-width:15ch}.opening{padding-bottom:20px}.opening p{font-size:16px}.scene img{max-height:220px;aspect-ratio:1.65}.work{display:block;margin-top:22px}.manuscript{margin-top:22px;padding:20px}.about{display:block}.about>div+div{margin-top:22px}.audition{min-height:0;padding:18px}h2{font-size:1.85rem}.listen{gap:8px}.listen button{flex:1}textarea{min-height:430px}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}}
</style></head><body>
<nav><a href="index.php">Chloe Reads Jon</a><span>A moon-sized occasion</span></nav><main>
<header class="opening"><h1>Small Speech,<br>Big Moment</h1><p>The Moon has its first playground. Your opening speech needs a little work. Try five edits and turn a sensible announcement into something worth standing up for.</p></header>
<figure class="scene"><img src="data:image/webp;base64," width="1536" height="1024" alt="A little astronaut at a lectern addresses a lunar playground's opening ceremony, with fellow astronauts and a curious rover listening."><figcaption>A fictional ceremony. A very real audience of six. And one rover.</figcaption></figure>
<div class="work" id="work"><section aria-label="Speech editing game"><div class="progress"><span id="progress"></span><div class="marks" aria-hidden="true" id="marks"></div></div><h2 id="roundTitle" tabindex="-1"></h2><p id="instruction"></p><blockquote class="audition" id="preview" aria-live="polite"></blockquote><div id="options" role="group" aria-label="Try an edit"></div><div class="actions"><button class="primary" id="check" disabled>Keep this line</button><button id="hint" aria-expanded="false" aria-controls="hintText">Give me a clue</button></div><p id="hintText" hidden></p><p id="feedback" role="status"></p><button id="next" class="primary" hidden>Next edit</button></section><details class="manuscript" id="manuscript" open><summary>Your speech so far</summary><ol id="script"></ol><p class="note">Every accepted line goes here. No timer. No penalty for trying a different edit.</p></details></div>
<section id="finish" hidden><h2 id="finishTitle" tabindex="-1">The Moon is listening.</h2><p>You have a speech! Read it aloud together, or change a few words to make it yours. The rover has promised not to heckle.</p><label for="finalText">Your opening-ceremony speech</label><textarea id="finalText" spellcheck="true"></textarea><div class="listen"><button class="primary" id="speak">Hear the speech</button><button id="stop" disabled>Stop reading</button><label for="pace">Pace <input id="pace" type="range" min="0.7" max="1.2" value="0.9" step="0.1"><output id="paceValue">0.9×</output></label></div><p id="audioStatus" role="status"></p><div class="actions"><button id="download">Save speech as text</button><button id="replay">Try the edits again</button></div><p class="note">Reading without audio? Pause at each full stop. Give the repeated words a little more weight. Look up for the final line.</p></section>
<section class="about"><div><h3>Why these little edits work</h3><p>Repetition gives listeners a foothold. Contrasts make a choice clear. Matching sentence shapes make a list easy to follow. Concrete images give an idea somewhere to land. A callback brings an ending home.</p><p>Good speeches still need something worth saying. These are tools for expressing an idea, not a machine for making any idea good.</p></div><div><h3>From Jon's listening list</h3><p>Inspired by Jon's <a href="small-speech-big-moment.php?source=1">Videos of Great Speeches: I Have A Dream; JFK's Inaugural Address</a>. His post sent me thinking about what makes a line memorable.</p><p>All the speech lines here are newly written for this game. They are not quotations or imitations of those speakers.</p></div></section></main><footer>Made for Jon &amp; Nathan. Original lunar ceremony art generated with GPT Image. Audio uses your browser's optional reading voice.</footer><noscript><p>Enable JavaScript to try the edits. The notes above explain the five techniques.</p></noscript>
<script>
'use strict';
const rounds=[
{title:'Give it a heartbeat',instruction:'Repeat the same opening words at the start of all three sentences. This is called anaphora.',plain:'We came to the Moon for science, exploration, and a place to play.',choices:['We came to learn. We came to explore. We came to play.','We came to learn. Exploration matters too. A playground is also useful.','We came, we came, we came. This playground is now open.'],answer:0,hint:'Listen to the beginning of each sentence. The repeated opening should introduce a new idea each time.',why:'“We came” begins three sentences, each moving the thought forward. Repeating the words alone would not build that rhythm.',wrong:['','The ideas fit, but their sentence openings do not match. Try the same two words three times.','That repeats words inside one sentence. Give each new sentence the same opening instead.']},
{title:'Make the contrast count',instruction:'Set two opposite ideas against each other in matching sentence shapes. This is antithesis.',plain:'This playground belongs to everyone, not just the fastest astronauts.',choices:['Fast astronauts like playgrounds. Slow astronauts may like them as well.','A place for the fastest and also, in addition, for everyone.','Not a prize for the few, but a place for us all.'],answer:2,hint:'Look for a matched “not ... but ...” structure and the contrast between a few and everyone.',why:'“A prize for the few” balances “a place for us all”. The contrast makes the promise easy to hear.',wrong:['The meaning is kind, but the opposite ideas do not sit in a balanced sentence.','The idea is there, but the extra joins blur the contrast. Try the more balanced version.','']},
{title:'Build three matching steps',instruction:'Make a three-part list in which every part starts with an action word. This is parallel structure in a tricolon.',plain:'We should share tools, take care of each other, and keep wondering.',choices:['Share our tools, kindness is important, and we wonder.','Share our tools, care for our neighbours, keep our curiosity.','Our tools, our neighbours, and the things we are curious about.'],answer:1,hint:'Find three verbs: share, care, keep. Each should begin a part of the list.',why:'“Share”, “care”, and “keep” give each part the same grammatical job. The three steps are easy to follow aloud.',wrong:['“Kindness is important” switches from an action to a statement. Keep the shapes matched.','','Those are three noun phrases, not the three action phrases requested.']},
{title:'Give the idea a picture',instruction:'Show cooperation as something the listeners can picture. Choose a metaphor: describe one thing as another, without “like”.',plain:'By working together, we can make a good home here.',choices:['Together, we are the roots of a garden in the dust.','Cooperation is an extremely beneficial way to achieve outcomes.','Working together is like tending a garden in the dust.'],answer:0,hint:'A metaphor says we ARE the roots. A simile would say we are LIKE the roots.',why:'Roots give support and help life grow. That concrete image carries the idea of a shared home. The version with “like” is a simile, also useful, but a different tool.',wrong:['','That explains the idea in abstract terms. There is nothing concrete to picture.','A lovely image, but “like” makes it a simile. This brief asks for a metaphor.']},
{title:'Bring the opening home',instruction:'Finish with a callback to the opening words “We came”. Then turn arrival into a next step.',plain:'The playground is open now. Have fun.',choices:['In conclusion, this concludes the official opening ceremony.','We came to play. Now let us build a place where everyone can.','The equipment has been checked. Please form a queue.'],answer:1,hint:'Which ending echoes “We came” and then looks ahead?',why:'The ending recalls the beginning and gives it a purpose: a place for everyone. A callback can make a short speech feel complete.',wrong:['That announces an ending without reconnecting to the opening.','','Useful instructions, but they do not echo your first line. Save them for after the applause.']}
];
const $=id=>document.getElementById(id);let stage=0,pick=-1,accepted=[],locked=false,utterance=null;
function manuscript(){let list=$('script');list.replaceChildren();rounds.forEach((r,i)=>{let li=document.createElement('li');li.textContent=accepted[i]||['An opening with a heartbeat','A promise for everyone','Three things to do','A picture to remember','An ending that comes home'][i];li.className=accepted[i]?'accepted':'pending';list.append(li);});}
function load(){pick=-1;locked=false;let r=rounds[stage];$('roundTitle').textContent=r.title;$('progress').textContent=`Edit ${stage+1} of 5`;$('marks').innerHTML=rounds.map((_,i)=>`<span class="${i<stage?'done':i===stage?'current':''}"></span>`).join('');$('instruction').textContent=r.instruction;$('preview').textContent=r.plain;$('options').replaceChildren();r.choices.forEach((c,i)=>{let b=document.createElement('button');b.textContent=c;b.setAttribute('aria-pressed','false');b.onclick=()=>{if(locked)return;pick=i;for(let v of $('options').children)v.setAttribute('aria-pressed',String(v===b));$('preview').textContent=c;$('check').disabled=false;$('feedback').textContent='Try saying it aloud. Does it fit the brief?';};$('options').append(b);});$('check').disabled=true;$('check').hidden=false;$('next').hidden=true;$('feedback').textContent='Choose a line to audition it above.';$('hintText').hidden=true;$('hintText').textContent=r.hint;$('hint').setAttribute('aria-expanded','false');$('hint').disabled=false;manuscript();}
$('hint').onclick=()=>{let open=$('hintText').hidden;$('hintText').hidden=!open;$('hint').setAttribute('aria-expanded',String(open));};
$('check').onclick=()=>{if(pick<0||locked)return;let r=rounds[stage];if(pick!==r.answer){$('feedback').textContent=r.wrong[pick];return;}locked=true;accepted.push(r.choices[pick]);$('feedback').textContent=r.why;$('next').hidden=false;$('next').textContent=stage===4?'Take the stage':'Next edit';$('next').focus();$('check').hidden=true;$('hint').disabled=true;for(let b of $('options').children)b.disabled=true;manuscript();};
$('next').onclick=()=>{stage++;if(stage<rounds.length){load();$('roundTitle').focus();}else{$('work').hidden=true;$('finish').hidden=false;$('finalText').value=accepted.join('\n\n');$('finishTitle').focus();}};
function stop(){if('speechSynthesis'in window)window.speechSynthesis.cancel();utterance=null;$('speak').disabled=false;$('stop').disabled=true;}
$('replay').onclick=()=>{stop();stage=0;accepted=[];$('finish').hidden=true;$('work').hidden=false;load();$('roundTitle').focus();};
$('pace').oninput=()=>{$('paceValue').textContent=Number($('pace').value).toFixed(1)+'×';};
$('speak').onclick=()=>{const text=$('finalText').value.trim();if(!text){$('audioStatus').textContent='Your speech is empty. Add a few words before reading.';$('finalText').focus();return;}if(!('speechSynthesis'in window)||!('SpeechSynthesisUtterance'in window)){$('audioStatus').textContent='This browser has no reading voice. You can still read aloud or save the speech.';return;}stop();utterance=new SpeechSynthesisUtterance(text);utterance.lang='en-CA';utterance.rate=Number($('pace').value);utterance.onend=()=>{stop();$('audioStatus').textContent='Speech finished. Your turn at the microphone.';};utterance.onerror=()=>{stop();$('audioStatus').textContent='The reading voice could not start. Try again, or read aloud from the script.';};$('audioStatus').textContent='Reading your speech. Press Stop reading to finish early.';$('stop').disabled=false;$('stop').focus();$('speak').disabled=true;window.speechSynthesis.speak(utterance);};
$('stop').onclick=()=>{stop();$('speak').focus();$('audioStatus').textContent='Reading stopped.';};
$('download').onclick=()=>{let t=$('finalText').value.trim();if(!t){$('audioStatus').textContent='Add a few words before saving your speech.';$('finalText').focus();return;}let url=URL.createObjectURL(new Blob([t+'\n'],{type:'text/plain;charset=utf-8'}));let a=document.createElement('a');a.href=url;a.download='our-moon-playground-speech.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('audioStatus').textContent='Your speech is ready to save as a text file.';};
window.addEventListener('pagehide',stop);if(matchMedia('(max-width:700px)').matches)$('manuscript').open=false;load();
</script></body></html>